// Race condition: two async operations on shared state
let balance = 1000;

async function withdraw(amount, label) {
  // Simulate a read-then-write that takes time (like a DB round-trip)
  const current = balance;                     // READ
  await new Promise(r => setTimeout(r, 10));   // simulate latency
  balance = current - amount;                  // WRITE (stale 'current'!)
  console.log(`${label}: withdrew ${amount}, new balance: ${balance}`);
}

// UNSAFE: both reads happen before either write
Promise.all([
  withdraw(200, 'Alice'),
  withdraw(300, 'Bob')
]).then(() => {
  console.log('Final balance:', balance);
  // Expected: 500  |  Actual: 700 or 800 — race condition!
});

// FIX: serialize with a simple async mutex
function createMutex() {
  let queue = Promise.resolve();
  return function withLock(fn) {
    queue = queue.then(fn);  // chain: next fn only runs after previous resolves
    return queue;
  };
}

const lock = createMutex();
balance = 1000;

lock(() => withdraw(200, 'Alice (safe)'));
lock(() => withdraw(300, 'Bob (safe)'));
// Now operations are serialized — correct final balance: 500

// Deadlock prevention strategy 1: consistent lock ordering
// WRONG — can deadlock if threadA acquires lockA first and threadB acquires lockB first
function transferWrong(from, to, amount) {
  from.lock();  // Thread A: acquires 'from'
  to.lock();    // Thread A: waits for 'to'  (Thread B may hold it)
  // ...transfer...
  to.unlock();
  from.unlock();
}

// RIGHT — always acquire locks in a globally consistent order (by account ID)
function transferSafe(accountA, accountB, amount) {
  const [first, second] = accountA.id < accountB.id
    ? [accountA, accountB]
    : [accountB, accountA];
  first.lock();
  second.lock();
  // ...transfer...
  second.unlock();
  first.unlock();
  // Eliminates circular wait (Coffman condition 4)
}

// Deadlock prevention strategy 2: lock with timeout
async function tryTransfer(from, to, amount, timeoutMs = 500) {
  const acquired = await from.tryLock(timeoutMs);
  if (!acquired) throw new Error('Lock timeout — retry later');
  try {
    await to.lock();
    // ...transfer...
  } finally {
    from.unlock();
  }
  // Breaks 'no preemption' by abandoning if lock not acquired in time
}
